<?php use Passport\Copy; ?>
<p class="eyebrow"><?= $e($t('STEWARDSHIP · PRIVATE')) ?></p><h1><?= $e($story['title']) ?></h1><p><?= $e($story['communityName']) ?> · <?= $e($t('Version')) ?> <?= $e($story['revision']) ?> · <span class="badge"><?= $e(\Passport\Copy::SHARING[$story['sharingState']]) ?></span></p><p><?= $e($t('Record only choices declared by the people involved. Changes retain a private history. Past approvals and ledger entries keep their original records.')) ?></p><div class="actions"><a href="/p/<?= $e($story['id']) ?>"><?= $e($t('passport')) ?> ↗</a><a href="/dashboard/requests"><?= $e($t('requests')) ?> ↗</a><a href="/ledger?storyId=<?= $e($story['id']) ?>"><?= $e($t('ledger')) ?> ↗</a></div>
<?php if (!$canWrite): ?><p class="notice"><?= $e($t('Your reviewer role can read this record and its history. Ask a community steward to make changes.')) ?></p><?php endif ?>
<?php if ($canWrite): ?>
<section class="card"><h2><?= $e($t('Sharing and visibility')) ?></h2><p><?= $e($t('Pause or withdraw sharing to hide content and stop new requests and approvals. Restrict visibility to keep a minimal contact passport. Withdrawing publication consent also hides public content. Earlier downloads cannot be recalled.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/edit" data-method="PATCH" data-reload><input type="hidden" name="action" value="sharing"><div class="two"><label><?= $e($t('Sharing state')) ?><select name="sharingState"><?php foreach (['ACTIVE'=>'Active','PAUSED'=>'Paused','WITHDRAWN'=>'Withdrawn'] as $value=>$label): ?><option value="<?= $e($value) ?>" <?= $story['sharingState']===$value?'selected':'' ?>><?= $e($t($label)) ?></option><?php endforeach ?></select></label><label><?= $e($t('Visibility')) ?><select name="sensitivity"><option value="OPEN" <?= $story['sensitivity']==='OPEN'?'selected':'' ?>><?= $e($t('Open, subject to publication consent')) ?></option><option value="RESTRICTED" <?= $story['sensitivity']==='RESTRICTED'?'selected':'' ?>><?= $e($t('Restricted')) ?></option></select></label></div><?php require __DIR__.'/revision-fields.php'; ?><button class="button"><?= $e($t('Save sharing choices')) ?></button><p class="form-message" role="status"></p></form></section>
<section class="card"><h2><?= $e($t('Story details')) ?></h2><p><?= $e($t('Correct the existing record rather than registering a duplicate. This editor keeps contributor identities and original media uploads intact. Contact the site operator for changes to those records.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/edit" data-method="PATCH" data-reload><input type="hidden" name="action" value="details"><label><?= $e($t('Title')) ?><input name="title" maxlength="200" required value="<?= $e($story['title']) ?>"></label><div class="two"><label><?= $e($t('Language')) ?><input name="language" maxlength="100" required value="<?= $e($story['language']) ?>"></label><label><?= $e($t('Coarse location (optional)')) ?><input name="placeCoarse" maxlength="100" value="<?= $e($story['placeCoarse']) ?>"></label></div><?php if ($story['mediaType']==='text'): ?><label><?= $e($t('Story text')) ?><textarea name="textBody" maxlength="100000" rows="8" required><?= $e($story['textBody']) ?></textarea></label><?php endif ?><label><?= $e($t('Context from the steward')) ?><textarea name="contextNote" maxlength="4000" required><?= $e($story['contextNote']) ?></textarea></label><?php require __DIR__.'/revision-fields.php'; ?><button class="button"><?= $e($t('Save story details')) ?></button><p class="form-message" role="status"></p></form></section>
<section class="card"><h2><?= $e($t('Consent, person by person')) ?></h2><form data-consent="<?= $e($story['id']) ?>"><?php foreach ($story['contributors'] as $person): ?><fieldset><legend><?= $e($person['name']) ?> · <?= $e($person['role']) ?></legend><div class="consent-tags"><?php foreach (Copy::PURPOSES as $purpose=>$label): ?><label class="check"><input type="checkbox" data-person="<?= $e($person['id']) ?>" data-purpose="<?= $e($purpose) ?>" <?= ($person['consents'][$purpose]['granted']??false)?'checked':'' ?>> <?= $e($label) ?></label><?php endforeach ?></div></fieldset><?php endforeach ?><?php require __DIR__.'/revision-fields.php'; ?><button class="button"><?= $e($t('Save declared consent')) ?></button><p class="form-message" role="status"></p></form></section>
<section class="card"><h2><?= $e($t('Declared terms and shares')) ?></h2><p><?= $e($t('Changes apply to future approvals. Shares must total 100%; existing ledger entries remain unchanged.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/edit" data-method="PATCH" data-terms data-reload><input type="hidden" name="action" value="terms"><label><?= $e($t('Declared terms')) ?><select name="preset"><?php foreach (Copy::PRESETS as $value=>$label): ?><option value="<?= $e($value) ?>" <?= $story['license']['preset']===$value?'selected':'' ?>><?= $e($label) ?></option><?php endforeach ?></select></label><label class="check"><input type="checkbox" name="aiTrainingAllowed" <?= $story['license']['aiTrainingAllowed']?'checked':'' ?>> <?= $e($t('Allow AI training only with every contributor’s specific consent')) ?></label><label><?= $e($t('Public steward contact email')) ?><input name="contactEmail" type="email" maxlength="254" required value="<?= $e($story['license']['contactEmail']) ?>"></label><label><?= $e($t('Terms notes')) ?><textarea name="notes" maxlength="2000"><?= $e($story['license']['notes']) ?></textarea></label><?php foreach ($story['contributors'] as $person): $share=array_values(array_filter($story['shares'],static fn(array $s):bool=>$s['contributorId']===$person['id']))[0]; ?><label><?= $e($person['name']) ?> · %<input type="number" min="0" max="100" step="0.01" required data-share-id="<?= $e($person['id']) ?>" value="<?= $e(number_format($share['bps']/100,2,'.','')) ?>"></label><?php endforeach ?><p data-share-total role="status"></p><label class="check"><input type="checkbox" name="termsConfirmed" required> <?= $e($t('I confirm these declared terms with the people involved.')) ?></label><label class="check"><input type="checkbox" name="sharesConfirmed" required> <?= $e($t('I confirm these percentage shares with the people involved.')) ?></label><?php require __DIR__.'/revision-fields.php'; ?><button class="button"><?= $e($t('Save terms and shares')) ?></button><p class="form-message" role="status"></p></form></section>
<section class="card"><h2><?= $e($t('Preferred attribution')) ?></h2><p><?= $e($t('Write the credit people should use, or leave it blank to use the title, creator and contributor names. The passport link is added automatically. Credit is public only while the story is publicly shared.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/edit" data-method="PATCH" data-reload><input type="hidden" name="action" value="credit"><label><?= $e($t('Preferred credit line')) ?><textarea name="preferredCredit" maxlength="2000"><?= $e($story['preferredCredit']) ?></textarea></label><?php require __DIR__.'/revision-fields.php'; ?><button class="button"><?= $e($t('Save preferred credit')) ?></button><p class="form-message" role="status"></p></form></section>
<section class="card"><h2><?= $e($t('Declared review status')) ?></h2><p><?= $e($t('Badges record a manual declaration, without independently verifying identity, authority or ownership. Changes to story details, terms or consent reset the badge to Unverified claim.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/status" data-method="PATCH" data-reload><label><?= $e($t('Status')) ?><select name="status"><?php foreach (Copy::STATUS as $value=>$label): ?><option value="<?= $e($value) ?>" <?= $story['status']===$value?'selected':'' ?>><?= $e($label) ?></option><?php endforeach ?></select></label><?php require __DIR__.'/revision-fields.php'; ?><button class="button secondary"><?= $e($t('Save status')) ?></button><p class="form-message" role="status"></p></form></section>
<?php if (!empty($actor['is_owner'])): ?><section class="card"><h2><?= $e($t('Community collection')) ?></h2><p><?= $e($t('Moving this record changes which team can access it, including its requests and ledger.')) ?></p><form data-api="/api/stories/<?= $e($story['id']) ?>/edit" data-method="PATCH" data-reload><input type="hidden" name="action" value="community"><label><?= $e($t('Collection')) ?><select name="communityId"><?php foreach ($communities as $community): ?><option value="<?= $e($community['id']) ?>" <?= $community['id']===$story['communityId']?'selected':'' ?>><?= $e($community['name']) ?></option><?php endforeach ?></select></label><?php require __DIR__.'/revision-fields.php'; ?><button class="button secondary"><?= $e($t('Move record')) ?></button><p class="form-message" role="status"></p></form></section><?php endif ?>
<?php endif ?>
<section class="card"><h2><?= $e($t('Private version history')) ?></h2><p><?= $e($t('Saved versions are read-only. Older content stays private to authorised team members, including when the current passport is restricted.')) ?></p><?php foreach ($history as $entry): ?><article class="history-row"><strong><?= $e($t('Version')) ?> <?= $e($entry['revision']) ?></strong><p><?= $e($entry['reason']) ?></p><p class="muted"><?= $e($entry['created_at']) ?> · <?= $e($entry['actor']??$t('System or legacy record')) ?></p><?php if (count($history)>1 || $entry['reason']==='Initial registration claim.'): ?><a href="/dashboard/stories/<?= $e($story['id']) ?>/history/<?= $e($entry['revision']) ?>"><?= $e($t('Read saved version')) ?> ↗</a><?php endif ?></article><?php endforeach ?></section>
